import java.math.BigInteger;

class Solution {
    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {
        BigInteger first = readNumber(l1);
        BigInteger second = readNumber(l2);
        String digits = first.add(second).toString();
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        for (int index = digits.length() - 1; index >= 0; index--) {
            tail.next = new ListNode(digits.charAt(index) - '0');
            tail = tail.next;
        }
        return dummy.next;
    }

    private BigInteger readNumber(ListNode head) {
        StringBuilder digits = new StringBuilder();
        while (head != null) {
            digits.append((char) ('0' + head.val));
            head = head.next;
        }
        return new BigInteger(digits.reverse().toString());
    }
}

